    "outcome" "text" NOT NULL,
    "cache_hit" boolean DEFAULT false NOT NULL,
    "rating" smallint,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ai_calls_outcome_check" CHECK (("outcome" = ANY (ARRAY['ok'::"text", 'invalid_output'::"text", 'failed_check'::"text", 'rate_limited'::"text", 'timeout'::"text", 'provider_error'::"text", 'limit_reached'::"text"]))),
    CONSTRAINT "ai_calls_rating_check" CHECK ((("rating" IS NULL) OR ("rating" = ANY (ARRAY['-1'::integer, 1]))))
);


